#include <iostream>
#include <cmath>

// Demonstrates mapping Cartesian coordinate (t, y) to screen coordinate (x, y_screen)
// with singularity guarding as described in Sinoverx()

int main() {
    const int midx = 320;
    const int midy = 240;
    const float pi = 3.14159265f;
    const float tileX = 50.0f / pi;
    const float tileY = 80.0f;

    std::cout << "Evaluation of Sinoverx samples around origin:\n";

    // Test sample points: x offset around midx
    int sample_x[] = { midx - 32, midx - 16, midx, midx + 16, midx + 32 };
    for (int x : sample_x) {
        // Exact float logic from textbook Sinoverx():
        float t = ((x == midx) ? 1.0f : static_cast<float>(x - midx)) / tileX;
        // Textbook uses integer truncation: int(sin(t)/t*tileY)
        int y_screen = midy - static_cast<int>(std::sin(t) / t * tileY);
        std::cout << "x=" << x 
                  << " -> delta_x=" << (x - midx)
                  << ", y_screen=" << y_screen << "\n";
    }
    return 0;
}

#include <iostream>
#include <cmath>

struct TOADO {
    int OX, OY, UX, UY, UZ;
    double Xx, Xy;
};

int projX(const TOADO& gr, double x, double y, double z) {
    return gr.OX + static_cast<int>(x * gr.UX * std::cos(gr.Xx) + y * gr.UY * std::cos(gr.Xy));
}

int projY(const TOADO& gr, double x, double y, double z) {
    return gr.OY + static_cast<int>(x * gr.UX * std::sin(gr.Xx) + y * gr.UY * std::sin(gr.Xy) - z * gr.UZ);
}

int main() {
    const double pi = 3.14159265358979323846;
    const int midx = 320;
    const int midy = 240;

    // 1. Hypocycloide point at t = 0
    double t0 = 0.0;
    int hyp_x0 = static_cast<int>(120 * std::pow(std::cos(t0), 3)) + midx;
    int hyp_y0 = static_cast<int>(120 * std::pow(std::sin(t0), 3)) + midy;

    // 2. Polar Rose point at t = pi/4
    double t_rose = pi / 4.0;
    int rose_x = static_cast<int>(150 * (std::sin(2 * t_rose) * std::cos(t_rose))) + midx;
    int rose_y = static_cast<int>(150 * std::sin(2 * t_rose) * std::sin(t_rose)) + midy;

    // 3. 3D Axonometric Projection with origin (0, 0, 0)
    TOADO gr3 = { 320, 20, 20, 20, 20, 0.8 * pi, 0.2 * pi };
    int sx0 = projX(gr3, 0.0, 0.0, 0.0);
    int sy0 = projY(gr3, 0.0, 0.0, 0.0);

    std::cout << "Hypocycloide(t=0): (" << hyp_x0 << ", " << hyp_y0 << ")\n";
    std::cout << "Rose(t=pi/4): (" << rose_x << ", " << rose_y << ")\n";
    std::cout << "3D Origin Screen Coord: (" << sx0 << ", " << sy0 << ")\n";

    return 0;
}
